package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.rollup.RollupService.Snapshot;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PersonService {

    private final PersonRepository people;
    private final PatronRepository patrons;
    private final SheetRepository sheets;
    private final SheetService sheetService;
    private final RollupService rollup;
    private final Audit audit;

    public PersonService(PersonRepository people, PatronRepository patrons, SheetRepository sheets, SheetService sheetService,
            RollupService rollup, Audit audit) {
        this.people = people;
        this.patrons = patrons;
        this.sheets = sheets;
        this.sheetService = sheetService;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet's people in the order they were added. */
    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        requireSheet(sheetId);
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    @Transactional
    public Person add(String user, String sheetId, String name, String grade) {
        requireSheet(sheetId);
        String trimmed = name.trim();
        requireNameFree(sheetId, trimmed, null);
        Snapshot before = rollup.snapshot(sheetId);
        Person person = people.saveAndFlush(new Person(sheetId, trimmed, grade));
        audit.recordOnCommit(entry("PERSON_ADDED", user, person, sheetService.today(sheetId)));
        rollup.recordChanges(user, sheetId, before);
        return person;
    }

    /**
     * Saves changes to a person. When {@code version} is given it is the version the editor loaded,
     * and the save is refused if the person has been saved since. The grade is recorded from {@code gradeFrom},
     * the sheet's today when none is given, keeping the grades the person has from other dates.
     */
    @Transactional
    public Person update(String user, String sheetId, Long id, String name, String grade, LocalDate gradeFrom,
            Long version) {
        LocalDate today = sheetService.today(sheetId);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        if (version != null && version != person.getVersion()) {
            throw changedMeanwhile();
        }
        String trimmed = name.trim();
        requireNameFree(sheetId, trimmed, id);
        Snapshot before = rollup.snapshot(sheetId);
        person.setName(trimmed);
        person.setGrade(grade, gradeFrom != null ? gradeFrom : today);
        try {
            people.flush();
        } catch (ObjectOptimisticLockingFailureException e) {
            throw changedMeanwhile();
        }
        audit.recordOnCommit(entry("PERSON_EDITED", user, person, today));
        rollup.recordChanges(user, sheetId, before);
        return person;
    }

    /** Retire the person from a date, the sheet's today when none is given; claims dated after it are refused. */
    @Transactional
    public Person retire(String user, String sheetId, Long id, LocalDate from) {
        LocalDate date = from != null ? from : sheetService.today(sheetId);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        person.setRetiredFrom(date);
        people.flush();
        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " from=" + date);
        return person;
    }

    /** Put the person on hold from a date, the sheet's today when none is given, to a to-date or open-ended; their
     * OPEN and PENDING claims dated within it, unless bound by a statement, count in no live total. A to-date before
     * the from-date is refused. */
    @Transactional
    public Person hold(String user, String sheetId, Long id, LocalDate from, LocalDate to) {
        LocalDate date = from != null ? from : sheetService.today(sheetId);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        if (to != null && to.isBefore(date)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A hold cannot end before it starts.");
        }
        Snapshot before = rollup.snapshot(sheetId);
        person.addHold(date, to);
        people.flush();
        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " from=" + date);
        rollup.recordChanges(user, sheetId, before);
        return person;
    }

    /** Each person's patrons' ids, by person id, in the order they were named. */
    @Transactional(readOnly = true)
    public Map<Long, List<Long>> patronIds(String sheetId) {
        Map<Long, List<Long>> by = new LinkedHashMap<>();
        for (Patron patron : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
            by.computeIfAbsent(patron.getPersonId(), k -> new ArrayList<>()).add(patron.getPatronId());
        }
        return by;
    }

    /** Name another person on the sheet as the person's patron; refused for the person themselves and for one
     * already named. */
    @Transactional
    public Person addPatron(String user, String sheetId, Long id, Long patronId) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron."));
        if (patron.getId().equals(person.getId())) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A person cannot be their own patron.");
        }
        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That patron is already named.");
        }
        patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId()));
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " patron=" + patron.getName());
        return person;
    }

    /** A line naming the person and the grade they have in force on the sheet's today. */
    private static String entry(String event, String user, Person person, LocalDate today) {
        return event + " sheet=" + person.getSheetId() + " by=" + user
                + " name=" + person.getName() + " grade=" + person.gradeOn(today);
    }

    private static ResponseStatusException changedMeanwhile() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
                "Someone else has saved that person since it was opened.");
    }

    private void requireNameFree(String sheetId, String name, Long exceptId) {
        if (people.nameInUse(sheetId, name, exceptId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
        }
    }

    private void requireSheet(String sheetId) {
        if (!sheets.existsById(sheetId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet.");
        }
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.Statement;
import net.officefloor.hq.app.statement.StatementService;
import net.officefloor.hq.app.statement.StatementService.Summary;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The people kept on a sheet. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/people")
public class PersonController {

    public record PersonForm(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate gradeFrom,
            Long version) {}

    /** A grade the person has from a from-date (none: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {}

    /** A hold on the person from a from-date to a to-date (none: open-ended). */
    public record HoldView(LocalDate from, LocalDate to) {}

    /** A person shows how many statements were taken for them and the last one's due-total (n/a when it was)
     * and date; none of those before the first; and the ids of their patrons, in the order they were named. Its
     * grade is the one in force on the sheet's today, and its grades every one recorded, by from-date. */
    public record PersonView(Long id, String name, String grade, List<GradeView> grades, long version, int statementCount,
            String statedTotal, LocalDate statementDate, LocalDate retiredFrom, boolean held,
            List<HoldView> holds, List<Long> patronIds) {

        public static PersonView of(Person person, LocalDate today, Map<Long, Summary> statements,
                Map<Long, List<Long>> patrons) {
            Summary summary = statements.get(person.getId());
            Statement last = summary != null ? summary.last() : null;
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
                    person.getGrades().stream().map(g -> new GradeView(g.getGrade(), g.getFrom())).toList(),
                    person.getVersion(),
                    summary != null ? summary.count() : 0,
                    last == null ? null : last.getDueTotal() != null ? last.getDueTotal().toPlainString() : "n/a",
                    last != null ? last.getTakenOn() : null, person.getRetiredFrom(), person.isHeld(),
                    person.getHolds().stream().map(h -> new HoldView(h.getFrom(), h.getTo())).toList(),
                    patrons.getOrDefault(person.getId(), List.of()));
        }
    }

    private final PersonService service;
    private final StatementService statements;
    private final SheetService sheets;

    public PersonController(PersonService service, StatementService statements, SheetService sheets) {
        this.service = service;
        this.statements = statements;
        this.sheets = sheets;
    }

    @GetMapping
    public List<PersonView> list(@RequestHeader("X-User") String user, @PathVariable String sheetId) {
        List<Person> people = service.list(sheetId);
        Map<Long, Summary> taken = statements.summaries(sheetId);
        Map<Long, List<Long>> patrons = service.patronIds(sheetId);
        LocalDate today = sheets.today(sheetId);
        return people.stream().map(p -> PersonView.of(p, today, taken, patrons)).toList();
    }

    @PostMapping
    public PersonView add(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @Valid @RequestBody PersonForm form) {
        return view(sheetId, service.add(user, sheetId, form.name(), form.grade()));
    }

    @PutMapping("/{id}")
    public PersonView update(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id, @Valid @RequestBody PersonForm form) {
        return view(sheetId, service.update(user, sheetId, id, form.name(), form.grade(), form.gradeFrom(),
                form.version()));
    }

    public record RetireForm(LocalDate from) {}

    /** Retire the person from a date, the sheet's today when none is given. */
    @PostMapping("/{id}/retire")
    public PersonView retire(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id, @RequestBody RetireForm form) {
        return view(sheetId, service.retire(user, sheetId, id, form.from()));
    }

    public record HoldForm(LocalDate from, LocalDate to) {}

    /** Put the person on hold from a date, the sheet's today when none is given, to a to-date or open-ended. */
    @PostMapping("/{id}/hold")
    public PersonView hold(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id, @RequestBody HoldForm form) {
        return view(sheetId, service.hold(user, sheetId, id, form.from(), form.to()));
    }

    public record PatronForm(@NotNull Long patronId) {}

    /** Name another person on the sheet as the person's patron. */
    @PostMapping("/{id}/patrons")
    public PersonView addPatron(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id, @Valid @RequestBody PatronForm form) {
        return view(sheetId, service.addPatron(user, sheetId, id, form.patronId()));
    }

    /** Take a statement for the person. */
    @PostMapping("/{id}/statement")
    public PersonView statement(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable Long id) {
        return view(sheetId, statements.take(user, sheetId, id));
    }

    private PersonView view(String sheetId, Person person) {
        return PersonView.of(person, sheets.today(sheetId), statements.summaries(sheetId), service.patronIds(sheetId));
    }
}

